import type { Metadata } from "next";

export const siteConfig = {
  name: "Covmerc",
  title: "Covmerc — Modern Furniture & Interior Studio",
  description:
    "Premium furniture and thoughtful interior design for modern living. Shop curated collections, explore design stories, and get expert support from Covmerc Studio.",
  url: process.env.NEXT_PUBLIC_SITE_URL ?? "https://covmerc.com",
  locale: "en_NG",
  twitterHandle: "@covmerc",
  /** Default social preview (generated by app/opengraph-image.tsx). */
  defaultOgImagePath: "/opengraph-image",
} as const;

const defaultOgImage = {
  url: siteConfig.defaultOgImagePath,
  width: 1200,
  height: 630,
  alt: siteConfig.title,
} as const;

/** Resolve product or external image URLs for Open Graph (must be absolute). */
export function resolveOgImageUrl(imageUrl?: string): string | undefined {
  if (!imageUrl?.trim()) return undefined;
  const trimmed = imageUrl.trim();
  if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
    return trimmed;
  }
  if (trimmed.startsWith("/")) {
    return `${siteConfig.url}${trimmed}`;
  }
  return trimmed;
}

export const defaultMetadata: Metadata = {
  metadataBase: new URL(siteConfig.url),
  title: {
    default: siteConfig.title,
    template: `%s | ${siteConfig.name}`
  },
  description: siteConfig.description,
  applicationName: siteConfig.name,
  keywords: [
    "Covmerc",
    "furniture",
    "modern interior",
    "Lagos furniture",
    "home decor",
    "ecommerce"
  ],
  authors: [{ name: siteConfig.name }],
  openGraph: {
    type: "website",
    locale: siteConfig.locale,
    url: siteConfig.url,
    siteName: siteConfig.name,
    title: siteConfig.title,
    description: siteConfig.description,
    images: [defaultOgImage],
  },
  twitter: {
    card: "summary_large_image",
    title: siteConfig.title,
    description: siteConfig.description,
    creator: siteConfig.twitterHandle,
    images: [siteConfig.defaultOgImagePath],
  },
  robots: {
    index: true,
    follow: true
  }
};

export function createPageMetadata({
  title,
  description,
  path = "",
  imageUrl
}: {
  title: string;
  description: string;
  path?: string;
  imageUrl?: string;
}): Metadata {
  const url = `${siteConfig.url}${path}`;
  const resolved = resolveOgImageUrl(imageUrl);
  const ogImages = resolved ? [{ url: resolved, alt: title }] : [defaultOgImage];

  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      title: `${title} | ${siteConfig.name}`,
      description,
      url,
      images: ogImages,
    },
    twitter: {
      title: `${title} | ${siteConfig.name}`,
      description,
      images: ogImages.map((entry) => entry.url),
    },
  };
}
